type View="today"|"journey"|"prepare"|"closet"|"review"|"check"; const goals:MorningGoal[]=["Calm","Productive","Centered","Energized","Prepared","Healthy","Unhurried","Flexible"];
const nav=[{id:"today",icon:"☀",label:"Today"},{id:"prepare",icon:"◇",label:"Prepare"},{id:"journey",icon:"↗",label:"Journey Map"},{id:"review",icon:"☾",label:"Review"},{id:"closet",icon:"♢",label:"Closet"}] as const;
