// TODO: Use a true hourly forecast for per-stop weather once the live provider supports it.
function Journey({events,stops,weather,date,now,prepState,socialMemory,togglePreparation,simulationLabel,change}:{events:ReadyEvent[];stops:JourneyStop[];weather:WeatherContext;date:string;now:Date;prepState:PreparationTaskState;socialMemory:SocialMemory;togglePreparation:(eventId:string,taskId:string)=>void;simulationLabel:string;change:()=>void}){
 const errandSchedule=useErrandSchedule(events,date,weather.location.timezone,now),scheduled=errandSchedule.suggestions.filter(slot=>slot.status==="scheduled"),noFit=errandSchedule.suggestions.filter(slot=>slot.status==="no-fit"),timelineItems=buildJourneyTimeline(events,stops,errandSchedule.errands,errandSchedule.suggestions);
 return <div className="page"><div className="page-title"><h1>Your Journey Map</h1><p>Fixed commitments and flexible windows Ready found around them.</p></div><div className="map-layout"><section className="timeline">{errandSchedule.ready&&timelineItems.map((item,i)=>{
  if(item.kind==="errand")return <article className="suggested-stop" key={`errand-${item.errand.id}`}><div className="time">{formatSlotTime(item.slot.startAt!,weather.location.timezone)}</div><div className="line"><span>✦</span></div><div className="stop-card"><small>READY FOUND A WINDOW</small><h3>{item.errand.title}</h3><p>{item.errand.estimatedMinutes} min{item.errand.location?` · ${item.errand.location}`:""}</p><em>{item.slot.reason}</em><div className="errand-actions"><button onClick={()=>errandSchedule.complete(item.errand.id)}>Complete</button><button onClick={()=>errandSchedule.reject(item.slot)}>Not then</button><button onClick={()=>errandSchedule.remove(item.errand.id)}>Remove</button></div></div></article>;
  const weatherLabel=i===0?`${weather.morningTemp}° · ${weather.currentCondition}`:i===timelineItems.length-1?`${weather.eveningTemp}°`:"";
  return <article key={item.stop.id}><div className="time">{item.stop.time}</div><div className="line"><span>{i+1}</span></div><div className="stop-card"><small>{item.stop.location}</small><h3>{item.stop.title}</h3>{weatherLabel&&<span className="weather-pill">{weatherLabel}</span>}{item.stop.note&&<p>↳ {item.stop.note}</p>}<JourneyPeoplePrep event={item.event} memory={socialMemory}/><div className="journey-prep"><EventPreparation event={item.event} timezone={weather.location.timezone} state={prepState} toggle={togglePreparation}/></div></div></article>
 })}{errandSchedule.ready&&timelineItems.length===0&&<EmptyState title="Your journey is open" detail="No fixed commitments or suggested errands today."/>}</section><aside className="map-side"><h3>Journey context</h3>{errandSchedule.notice&&<div className="journey-errand-notice" role="status">{errandSchedule.notice}</div>}<p><span>UV</span><b>UV {weather.uvIndex} at midday</b><small>{weather.uvIndex>=6?"Sunscreen before leaving":"Lower UV today"}</small></p>{weather.precipitationStart&&<p><span>☂</span><b>Rain after {weather.precipitationStart}</b><small>Umbrella for your evening</small></p>}<p><span>✦</span><b>{scheduled.length} flexible {scheduled.length===1?"errand":"errands"}</b><small>Windows Ready found without assuming travel time</small></p>{noFit.length>0&&<p className="journey-attention"><span>!</span><b>{noFit.length} {noFit.length===1?"errand needs":"errands need"} a time</b><small>Review under Today or Prepare</small></p>}{events.length===0&&<small>No timed journey events today.</small>}{simulationLabel&&<button onClick={change}>{simulationLabel}</button>}</aside></div></div>
}
function JourneyPeoplePrep({event,memory}:{event:ReadyEvent;memory:SocialMemory}){const [expanded,setExpanded]=useState(false),result=memory.results.find(item=>item.event.id===event.id);if(!memory.ready||!result)return null;return <div className="journey-people"><button onClick={()=>setExpanded(!expanded)} aria-expanded={expanded}><span>✦</span><b>{result.person.name} · {relationshipLabel(result.person)}</b><small>People Prep available</small></button>{expanded&&<ul>{result.bullets.map(bullet=><li key={bullet.id}><span><b>{categoryLabel(bullet.category)}</b>{bullet.text}</span><button aria-label={`Dismiss reminder: ${bullet.text}`} onClick={()=>memory.dismiss(event.id,bullet.id)}>×</button></li>)}</ul>}</div>}
function formatTomorrowBadge(date:string){const [year,month,day]=date.split("-").map(Number),tomorrow=new Date(Date.UTC(year,month-1,day+1,12));return new Intl.DateTimeFormat("en-US",{weekday:"short",day:"numeric",timeZone:"UTC"}).format(tomorrow).toUpperCase()}
